async ({ shell: { execFile }, delivery: { format, validate } }) => {
  const i = await execFile("npm", ["ci"], { timeoutMs: 200000, maxLines: 10, truncate: "tail" });
  if (i.code) return i;
  const f = await format();
  const v = await validate();
  const d = await execFile("date", ["-u", "+%F"]);
  return { f, v, d: d.stdout };
